import requests
import json

# Basic masking: User-Agent header
headers = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36',
    'Content-Type': 'application/json',
    # You would typically need a Client-ID and possibly other headers like device-id
    # 'Client-ID': 'your_client_id_here', 
}

# This is a hypothetical GraphQL mutation for registration.
# The actual operation name and variables structure would need to be captured from real traffic.
graphql_query = {
    "operationName": "RegisterUser",
    "variables": {
        "input": {
            "username": "testuser12345",
            "password": "StrongPassword123!",
            "email": "testuser12345@example.com",
            "birthday": {
                "day": 1,
                "month": 1,
                "year": 1990
            }
        }
    },
    "query": "mutation RegisterUser($input: RegisterUserInput!) { registerUser(input: $input) { user { id username } error { code message } } }"
}

# Twitch GraphQL endpoint
url = "https://gql.twitch.tv/graphql"

print("Sending simulated registration request...")

try:
    response = requests.post(url, headers=headers, data=json.dumps(graphql_query))
    print(f"Status Code: {response.status_code}")
    print("Response Body:")
    print(response.text)

except Exception as e:
    print(f"An error occurred: {e}")
